package android.database; import java.util.*;
public final class MatrixCursor implements Cursor { private final String[] columns; private final List<Object[]> rows=new ArrayList<>(); private int pos=-1; public MatrixCursor(String[] columns){this.columns=columns;} public void addRow(Object[] row){rows.add(row);} public boolean moveToFirst(){pos=rows.isEmpty()?-1:0;return pos>=0;} public boolean moveToNext(){if(pos<rows.size())pos++;return pos>=0&&pos<rows.size();} private Object at(int i){if(pos<0||pos>=rows.size())throw new IllegalStateException("cursor position");return rows.get(pos)[i];} public long getLong(int i){Object v=at(i);return v==null?0:v instanceof Number?((Number)v).longValue():Long.parseLong(String.valueOf(v));} public int getInt(int i){return (int)getLong(i);} public String getString(int i){Object v=at(i);return v==null?null:String.valueOf(v);} public int getColumnIndex(String n){for(int i=0;i<columns.length;i++)if(columns[i].equals(n))return i;return -1;} public boolean isNull(int i){return at(i)==null;} public void close(){} }
